// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: an address 'from', an address 'caddress' (we will deploy a helper and use its address),
    // a uint v, and a dynamic array length encoded via bytes to let fuzzer vary _tos contents.
    function testFuzz_property(address from, uint256 v, bytes memory tosData) public {
        // We must ensure there is at least one element in _tos to exercise the require in transfer.
        // The fuzzer provides tosData; interpret it as concatenated addresses and build an address[] with length >= 1.
        // Keep domain wide: require tosData not empty; otherwise construct a single-element array using address(0).

        address[] memory _tos;
        if (tosData.length < 20) {
            // ensure at least one entry
            _tos = new address[](1);
            _tos[0] = address(0x1234);
        } else {
            // parse as many full 20-byte addresses as available, up to a reasonable cap to avoid too large arrays
            uint maxEntries = 8;
            uint entries = tosData.length / 20;
            if (entries == 0) { entries = 1; }
            if (entries > maxEntries) { entries = maxEntries; }
            _tos = new address[](entries);
            for (uint i = 0; i < entries; i++) {
                uint offset = i * 20;
                bytes20 b;
                for (uint j = 0; j < 20; j++) {
                    b |= bytes20(tosData[offset + j]) >> (j * 8);
                }
                // cast bytes20 to address
                _tos[i] = address(uint160(uint256(uint160(b))));
            }
        }

        // Deploy an adversarial callee that simply returns true for calls to transferFrom signature so
        // the reference contract's inner calls succeed; this ensures the reference returns true.
        // Mutant skips calling entirely and returns false, causing a differing return value.
        CalleeResponder callee = new CalleeResponder();

        // Drive the call and capture whether it returned (ok) and what the returned boolean was when possible.
        bool ok;
        bool ret;
        // call and capture success and return using low-level try/catch on the external call
        try c.transfer(from, address(callee), _tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // General property: for every admissible input (require _tos.length>0), the reference contract returns true (and thus ok==true and ret==true).
        // We assert on c's observable behavior (the return success and value). The mutant will for some inputs return false while the reference returns true.
        // Ensure we invoked with non-empty _tos to satisfy require in transfer
        assertTrue(ok && ret);
    }
}

// Minimal helper that responds to the low-level call invoked by C with the expected selector.
contract CalleeResponder {
    // Implement a fallback that checks selector and returns true (encoded as bool) for transferFrom calls
    fallback() external payable {
        // decode selector and arguments not necessary; just return true encoded
        bytes memory ret = abi.encode(true);
        assembly { 
            let ptr := add(ret, 32)
            let size := mload(ret)
            returndatacopy(ptr, ptr, size)
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: from address, v amount (uint256), and a bytes representing encoded array of to addresses
    // We will decode calldata-like bytes into an address[] to allow the fuzzer to pick array length and entries.
    function testFuzz_property(address from, uint256 v, bytes memory tosEncoded) public {
        // admissible domain: require non-empty tos array (the property concerns non-empty _tos)
        // decode tosEncoded as array of addresses; to keep domain wide permit lengths up to, say, 8
        // Simple decoding: first byte = length (0..8), followed by that many 20-byte addresses (padded if short)
        uint8 maxLen = 8;
        uint8 len = 0;
        if (tosEncoded.length > 0) {
            len = uint8(uint8(tosEncoded[0]) % (maxLen + 1));
        }
        // We need non-empty arrays only, so assume len > 0
        vm.assume(len > 0);

        address[] memory tos = new address[](len);
        // fill addresses from tosEncoded; if insufficient bytes, use address(0)
        for (uint i = 0; i < len; i++) {
            uint start = 1 + i * 20;
            address a = address(0);
            if (tosEncoded.length >= start + 20) {
                // read 20 bytes
                bytes20 b;
                assembly { b := mload(add(add(tosEncoded, 0x14), start)) }
                a = address(uint160(uint256(b)));
            }
            tos[i] = a;
        }

        // Deploy a helper callee that always succeeds to keep behaviour deterministic; we still pass its address
        // because C uses low-level call to caddress — calling an EOA would also succeed but helper ensures consistent behavior
        CalleeSucceeds cal = new CalleeSucceeds();
        address calAddr = address(cal);

        // Call transfer and capture the boolean return using try/catch to observe completion and returned value
        bool ok;
        bool retval;
        try c.transfer(from, calAddr, tos, v) returns (bool r) {
            ok = true;
            retval = r;
        } catch {
            ok = false;
            retval = false;
        }

        // The general rule: for every admissible input (we ensured tos.length > 0), the reference C returns true (and completes).
        // So we assert that the call completed and returned true. This holds for the reference; the mutant can return false.
        assertTrue(ok && retval);
    }
}

// Minimal helper that returns successfully when its transferFrom selector is called.
contract CalleeSucceeds {
    // accept any calldata and return true by not reverting
    fallback() external payable {}
}
